[[gnu::flatten, gnu::noinline]]
void kernel_2mm(num_t alpha, num_t beta, auto tmp, auto A, auto B, auto C, auto D) {
	using namespace noarr;

	// Tuning knobs for potential future blocking; marked maybe_unused so
	// that they can be wired into into_blocks/hoist without warnings.
	[[maybe_unused]] constexpr std::size_t K_BLOCK = 64;
	[[maybe_unused]] constexpr std::size_t L_BLOCK = 64;

#pragma scop

	// -----------------------------------------------------------------
	// Pre-pass 1: zero tmp[i][j]
	// -----------------------------------------------------------------
	traverser(tmp).for_each([&](auto s) {
		tmp[s] = (num_t)0;
	});

	// -----------------------------------------------------------------
	// Pre-pass 2: scale D[i][l] by beta
	// -----------------------------------------------------------------
	traverser(D).for_each([&](auto s) {
		D[s] *= beta;
	});

	// -----------------------------------------------------------------
	// Phase 1: tmp[i][j] += alpha * A[i][k] * B[k][j]
	//
	// Loop order: i (outer) – k (middle) – j (inner)
	//
	//  - A: layout k inner, i outer  -> we fix (i,k) and reuse A[i,k]
	//  - B: layout j inner, k outer  -> j is innermost  -> unit-stride
	//  - tmp: layout j inner, i outer -> j is innermost -> unit-stride
	// -----------------------------------------------------------------
	traverser(tmp, A, B).template for_dims<'i'>([&](auto trav_i) {
		// i is fixed here
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// i and k are fixed here

			// Load A[i][k] once and reuse across all j for this (i,k)
			const num_t aik = A[trav_ik];

			trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
				// i, k, j are fixed here
				tmp[trav_ikj] += alpha * aik * B[trav_ikj];
			});
		});
	});

	// -----------------------------------------------------------------
	// Phase 2: D[i][l] += sum_j tmp[i][j] * C[j][l]
	//           (D already scaled by beta)
	//
	// Loop order: j (outer) – i (middle) – l (inner)
	//
	//  - C: layout l inner, j outer  -> l innermost -> unit-stride
	//  - D: layout l inner, i outer  -> l innermost -> unit-stride
	//  - tmp: layout j inner, i outer
	//      we fix (i,j) and reuse tmp[i][j] across all l
	// -----------------------------------------------------------------
	traverser(D, tmp, C).template for_dims<'j'>([&](auto trav_j) {
		// j is fixed here
		trav_j.template for_dims<'i'>([&](auto trav_ij) {
			// j and i are fixed here

			// Load tmp[i][j] once and reuse across all l
			const num_t tij = tmp[trav_ij];

			trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
				// j, i, l are fixed here
				D[trav_ijl] += tij * C[trav_ijl];
			});
		});
	});

#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem sizes
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;

