	// traverser(A, B, tmp) sees the union of dimensions {i, j, k}.
	//  - for_dims<'i'> fixes i
	//  - for_dims<'k'> fixes k as well
	//  - for_each on trav_ik then iterates the remaining dimension j
	traverser(A, B, tmp)
