			// 'i' is fixed here.
			trav_i.template for_dims<'k'>([&](auto trav_ik) {
				// 'i' and 'k' are fixed here.

				// A[i][k] is reused for all j; pre-scale by alpha to avoid
				// recomputing alpha * A[i][k] in the inner j-loop.
				const num_t a_ik_scaled = alpha * A[trav_ik];

				// Iterate over all j for this (i,k) pair. The state passed to
			 // the lambda has indices (i,k,j). Extra indices are harmless
				// for each bag: each bag uses only the dimensions it knows.
				trav_ik.for_each([&](auto state_ikj) {
					// state_ikj: {i, k, j}
					//   tmp[i][j] += alpha * A[i][k] * B[k][j]
					tmp[state_ikj] += a_ik_scaled * B[state_ikj];
				});
			});
		});

	// ---------------------------------------------------------------------
	// Phase 2: D[i][l] = beta * D[i][l] + sum_j tmp[i][j] * C[j][l]
	// ---------------------------------------------------------------------

