				// dimension 'l'. The state now carries {i, j, l}.
				trav_ij.for_each([&](auto state_ijl) {
					// D[i][l] += tmp[i][j] * C[j][l]
					D[state_ijl] += tmp_ij * C[state_ijl];
				});
			});
		});
