//      This streamed A nicely, but accessed B and tmp with a large stride
//      in the innermost loop.
//    - New loop order: i, k, j
//      For each (i, k) we read A[i][k] once, then
//        - stream an entire row B[k][*] contiguously in j
//        - update an entire row tmp[i][*] contiguously in j
//      This improves spatial locality for both B and tmp, while
//      still streaming A across k for each i.
//
// 2) Phase 2 (D = beta*D + tmp*C)
//    - Original loop order: i, l, j
//      This accessed C with a large stride in the inner loop.
//    - New loop order: i, j, l
//      For each (i, j) we read tmp[i][j] once, then
//        - stream row C[j][*] in l
//        - stream row D[i][*] in l
//      This improves locality for both C and D and enables a
//      vector-friendly innermost loop along l.
//
// 3) Reductions are still performed as plain sequential sums over k (phase 1)
//    and j (phase 2). The algebraic result is the same as in the original
//    kernel (modulo usual floating‑point round-off behaviour).
// -----------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_2mm(num_t alpha, num_t beta, auto tmp, auto A, auto B, auto C, auto D) {
	using namespace noarr;

#pragma scop
	// -------------------------------------------------------------------------
	// First phase: tmp[i][j] = alpha * sum_k A[i][k] * B[k][j]
	// -------------------------------------------------------------------------

	// 1) Explicitly zero tmp so that the main accumulation below is
	//    purely additive. This also gives the compiler a very simple,
	//    vectorizable loop.
	traverser(tmp).for_each([&](auto s) {
		tmp[s] = (num_t)0;
	});

	// 2) Accumulate in i-k-j order:
	//    for i
	//      for k
	//        a_ik = A[i][k];
	//        for j
	//          tmp[i][j] += alpha * a_ik * B[k][j];
	//
	//    Both B[k][j] and tmp[i][j] are stored row-major with 'j' as the
	//    inner dimension, so the innermost loop streams contiguous memory.
	traverser(tmp, A, B).template for_dims<'i'>([&](auto trav_i) {
		// i is fixed here
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// i and k are fixed here: one A(i,k) reused for all j at this (i,k)
			const num_t a_ik = A[trav_ik];

			// j is the only remaining free dimension
			trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
				tmp[trav_ikj] += alpha * a_ik * B[trav_ikj];
			});
		});
	});

	// -------------------------------------------------------------------------
	// Second phase: D[i][l] = beta * D[i][l] + sum_j tmp[i][j] * C[j][l]
	// -------------------------------------------------------------------------

	// 1) Scale D by beta once. This preserves the original semantics
	//    where each D[i][l] was multiplied by beta exactly once before
	//    the accumulation over j.
	traverser(D).for_each([&](auto s) {
		D[s] *= beta;
	});

	// 2) Accumulate in i-j-l order:
	//    for i
	//      for j
	//        t = tmp[i][j];
	//        for l
	//          D[i][l] += t * C[j][l];
	//
	//    C[j][l] and D[i][l] are row-major with 'l' inner, so the
	//    innermost loop streams rows of C and D along l.
	traverser(D, tmp, C).template for_dims<'i'>([&](auto trav_i) {
		// i is fixed here
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			// i and j are fixed here
			const num_t tmp_ij = tmp[trav_ij];

			// l is the remaining free dimension; iterate it innermost
			trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
				D[trav_ijl] += tmp_ij * C[trav_ijl];
			});
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem sizes
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;

	// scalars
	num_t alpha;
	num_t beta;

	// set all potential lengths once; each layout will use the relevant ones
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl);

	// allocate bags with given layouts and lengths
	auto tmp = noarr::bag(noarr::scalar<num_t>() ^ tuning.tmp_layout ^ set_lengths);
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout   ^ set_lengths);
	auto B   = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout   ^ set_lengths);
	auto C   = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout   ^ set_lengths);
	auto D   = noarr::bag(noarr::scalar<num_t>() ^ tuning.d_layout   ^ set_lengths);

	// initialize arrays
	init_array(alpha, beta, A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	// measure execution time
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_2mm(alpha, beta, tmp.get_ref(), A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optionally dump the resulting D matrix (layout-agnostic)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' to be the outer dimension for row-wise printing
		noarr::serialize_data(std::cerr, D.get_ref() ^ noarr::hoist<'i'>());
	}

	// print elapsed time (seconds)
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
